### Example 1 — Exception Hierarchy for an Application

```python
class AppError(Exception):
    """Base exception for the application."""
    def __init__(self, message, error_code=None):
        super().__init__(message)
        self.error_code = error_code

class ValidationError(AppError):
    """Raised when input validation fails."""
    def __init__(self, field, message):
        super().__init__(f"Validation error on '{field}': {message}")
        self.field = field

class NotFoundError(AppError):
    """Raised when a resource is not found."""
    def __init__(self, resource, resource_id):
        super().__init__(f"{resource} with id '{resource_id}' not found", error_code="NOT_FOUND")
        self.resource = resource
        self.resource_id = resource_id

class AuthenticationError(AppError):
    """Raised when authentication fails."""
    pass

class AuthorizationError(AppError):
    """Raised when user lacks permissions."""
    def __init__(self, action, resource):
        super().__init__(f"Not authorized to {action} on {resource}", error_code="FORBIDDEN")

# Usage
def get_user(user_id):
    if not isinstance(user_id, int):
        raise ValidationError("user_id", "Must be an integer")
    if user_id <= 0:
        raise ValidationError("user_id", "Must be positive")
    # Simulate not found
    raise NotFoundError("User", user_id)

try:
    get_user(999)
except NotFoundError as e:
    print(f"Error: {e}")           # Error: User with id '999' not found
    print(f"Resource: {e.resource}") # Resource: User
    print(f"Code: {e.error_code}")   # Code: NOT_FOUND
except ValidationError as e:
    print(f"Validation: {e.field}")
except AppError as e:
    print(f"App error: {e}")
```

### Example 2 — Exception with HTTP Status

```python
class HTTPError(Exception):
    status_code = 500

    def __init__(self, message=None):
        self.message = message or self.__class__.__doc__
        super().__init__(self.message)

    def to_dict(self):
        return {
            "error": self.__class__.__name__,
            "message": self.message,
            "status_code": self.status_code,
        }

class BadRequest(HTTPError):
    """Bad request — invalid input."""
    status_code = 400

class Unauthorized(HTTPError):
    """Authentication required."""
    status_code = 401

class Forbidden(HTTPError):
    """Access denied."""
    status_code = 403

class NotFound(HTTPError):
    """Resource not found."""
    status_code = 404

# Usage in an API handler
try:
    raise NotFound("User not found")
except HTTPError as e:
    response = e.to_dict()
    print(response)
    # {'error': 'NotFound', 'message': 'User not found', 'status_code': 404}
```
